void AVLTree<T>::_preOrder(Node<T> *r, std::ostream &out) const {
    if (r) {
        out << r->value << "\t\t(BF: " << r->bFactor << ")" << std::endl;
        _preOrder(r->left, out);
        _preOrder(r->right, out);
