template <typename T>
void AVLTree<T>::_postOrder(Node<T> *r, std::ostream &out) const {
    if (r) {
        _postOrder(r->left, out);
        _postOrder(r->right, out);
        out << r->value << "\t\t(BF: " << r->bFactor << ")" << std::endl;
