//*****************************************************************************************************

template <typename T>
T *AVLTree<T>::_search(Node<T> *r, const T &item) const {
    T *result = nullptr;

    if (r) {
        if (item > r->value)
            result = _search(r->right, item);
        else if (item < r->value)
            result = _search(r->left, item);
        else
            result = new T(r->value);
    }

    return result;
}

