    HashTable<Stock> stockTable(10);

    Stock google("Google", "GOOGL", 1500.50);
    Stock apple("Apple", "AAPL", 140.30);
    Stock microsoft("Microsoft", "MSFT", 220.10);
    Stock tesla("Tesla", "TSLA", 420.69);
    Stock amazon("Amazon", "AMZN", 3000.00);
