        cout << "Stock found!\n"
             << *searchResult << endl;

        delete searchResult;
        searchResult = nullptr;

        table.remove(item);
        cout << "\nAfter Removal of " << item.getSymbol() << ":" << endl;
        table.display();
    } else {
        cerr << "Stock not found!\n";
    }
}

